import { useEffect, useState } from 'react';
import axios from '../api/axios';
import jwtDecode from 'jwt-decode'; // Corrected import
import { useNavigate } from 'react-router-dom';

function Events() {
  const [events, setEvents] = useState([]);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [isAdmin, setIsAdmin] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const res = await axios.get('/events');
        setEvents(res.data);
      } catch (err) {
        console.error('Fetch Events Error:', err);
        setError('Failed to fetch events');
      }
    };

    const checkUserRole = () => {
      const token = localStorage.getItem('token');
      if (token) {
        try {
          const decoded = jwtDecode(token); // Corrected usage
          if (decoded.role === 'admin') setIsAdmin(true);
        } catch (e) {
          console.error('Token decode error', e);
        }
      }
    };

    fetchEvents();
    checkUserRole();
  }, []);

  const handleRegister = async (eventId) => {
    const token = localStorage.getItem('token');
    if (!token) {
      setError('Login required to register for events.');
      return;
    }

    try {
      const res = await axios.post(
        '/registration/register-event',
        { eventId },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      setMessage(res.data.message || 'Registered successfully');
      setError('');
    } catch (err) {
      console.error('Registration Error:', err);
      setMessage('');
      setError(err.response?.data?.message || 'Registration failed');
    }
  };

  return (
    <div className="container mt-4">
      <h2>All Events</h2>

      {message && <div className="alert alert-success">{message}</div>}
      {error && <div className="alert alert-danger">{error}</div>}

      {events.length === 0 ? (
        <p>No events found</p>
      ) : (
        <div className="row">
          {events.map(event => (
            <div key={event._id} className="col-md-4 mb-4">
              <div className="card">
                <div className="card-body">
                  <h5 className="card-title">{event.title}</h5>
                  <p className="card-text">{event.description}</p>
                  <p><strong>Date:</strong> {new Date(event.date).toLocaleDateString()}</p>
                  <p><strong>Location:</strong> {event.location}</p>
                  <p><small>By: {event.createdBy?.name || 'Admin'}</small></p>

                  <button
                    className="btn btn-primary mt-2 me-2"
                    onClick={() => handleRegister(event._id)}
                  >
                    Register
                  </button>

                  {isAdmin && (
                    <button
                      className="btn btn-secondary mt-2"
                      onClick={() => navigate(`/registrations/${event._id}`)}
                    >
                      View Registrations
                    </button>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Events;
